REVOKE ALL ON TABLE public.indicator_reporting_snapshots FROM anon,authenticated;
CREATE OR REPLACE FUNCTION app_private.list_results_snapshots(_indicator uuid) RETURNS SETOF public.indicator_reporting_snapshots LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.* FROM public.indicator_reporting_snapshots s WHERE s.indicator_id=_indicator AND public.results_indicator_access(_indicator) ORDER BY s.period_start DESC,s.version DESC $$;
CREATE OR REPLACE FUNCTION public.list_results_snapshots(_indicator uuid) RETURNS SETOF public.indicator_reporting_snapshots LANGUAGE sql STABLE SET search_path=public AS $$ SELECT * FROM app_private.list_results_snapshots(_indicator) $$;
CREATE OR REPLACE FUNCTION app_private.approve_results_period(_indicator uuid,_start date,_end date,_amends uuid DEFAULT NULL,_reason text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; org uuid; BEGIN SELECT organization_id INTO org FROM public.indicators WHERE id=_indicator; IF NOT public.results_indicator_access(_indicator) OR NOT public.donor_review_allowed(org) THEN RAISE EXCEPTION 'Approval access denied'; END IF; INSERT INTO public.indicator_reporting_snapshots(organization_id,indicator_id,period_start,period_end,version,amends_id,amendment_reason,snapshot,approved_by) VALUES(org,_indicator,_start,_end,1,_amends,_reason,'{}',auth.uid()) RETURNING id INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.approve_results_period(_indicator uuid,_start date,_end date,_amends uuid DEFAULT NULL,_reason text DEFAULT NULL) RETURNS uuid LANGUAGE sql SET search_path=public AS $$ SELECT app_private.approve_results_period(_indicator,_start,_end,_amends,_reason) $$;
REVOKE ALL ON FUNCTION app_private.list_results_snapshots(uuid),app_private.approve_results_period(uuid,date,date,uuid,text),public.list_results_snapshots(uuid),public.approve_results_period(uuid,date,date,uuid,text),public.compute_results_indicator(uuid,date,date),public.results_indicator_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION app_private.list_results_snapshots(uuid),app_private.approve_results_period(uuid,date,date,uuid,text),public.list_results_snapshots(uuid),public.approve_results_period(uuid,date,date,uuid,text),public.compute_results_indicator(uuid,date,date),public.results_indicator_access(uuid) TO authenticated;
NOTIFY pgrst,'reload schema';